import { revalidateTag } from 'next/cache';
import { getAllProducts } from '../lib/db';

// Cached component that fetches product data
async function ProductList() {
  'use cache';

  const products = await getAllProducts();

  return (
    <div style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px', marginBottom: '20px' }}>
      <h2>Product Listing (Cached)</h2>
      <p style={{ color: '#666', fontSize: '14px' }}>
        Last fetched: {new Date().toLocaleTimeString()}
      </p>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product) => (
          <li key={product.id} style={{ padding: '10px', borderBottom: '1px solid #eee' }}>
            <strong>{product.name}</strong> - ${product.price}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function Page() {
  // Server action for cache invalidation
  async function invalidateProductCache() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto' }}>
      <h1>Efficient Data Caching Demo</h1>
      <p style={{ marginBottom: '30px', color: '#555' }}>
        This page demonstrates Next.js caching with selective invalidation.
        The product list is cached and will only be refetched when you click the button below.
      </p>

      <ProductList />

      <form action={invalidateProductCache}>
        <button
          type="submit"
          style={{
            padding: '12px 24px',
            backgroundColor: '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '16px',
            fontWeight: '500'
          }}
        >
          Invalidate Product Cache
        </button>
      </form>

      <div style={{ marginTop: '30px', padding: '15px', backgroundColor: '#f5f5f5', borderRadius: '6px' }}>
        <h3 style={{ marginTop: 0 }}>How it works:</h3>
        <ol style={{ lineHeight: '1.8' }}>
          <li><strong>Caching:</strong> ProductList uses 'use cache' directive with 'products' tag</li>
          <li><strong>Performance:</strong> Cached data is served instantly without database calls</li>
          <li><strong>Invalidation:</strong> Click button to trigger revalidateTag('products')</li>
          <li><strong>Refresh:</strong> After invalidation, the next render fetches fresh data</li>
        </ol>
      </div>
    </div>
  );
}

